def parse_test_results(lines):
    counts = {"passed": 0, "failed": 0, "skipped": 0}
    prefixes = {
        "PASS:": "passed",
        "FAIL:": "failed",
        "SKIP:": "skipped",
    }

    for line in lines:
        for prefix, key in prefixes.items():
            if line.startswith(prefix):
                counts[key] += 1
                break

    return counts

