solution:
def missing_bins(required, observed):
    observed_set = set(observed)
    missing = []
    seen = set()

    for bin_name in required:
        if bin_name not in observed_set and bin_name not in seen:
            missing.append(bin_name)
            seen.add(bin_name)

    return missing

