solution:
def summarize_logs(logs):
    passed = 0
    failed = 0
    failed_logs = []
    for name, lines in logs.items():
        log_failed = False
        for line in lines:
            if line.startswith('PASS:'):
                passed += 1
            elif line.startswith('FAIL:'):
                failed += 1
                log_failed = True
        if log_failed:
            failed_logs.append(name)
    return {'logs': len(logs), 'passed': passed, 'failed': failed, 'failed_logs': sorted(failed_logs)}

